<template>
  <div class="page">
    <PageHeader title="数据分析" desc="使用本地算法分析表格与时序数据；分析结果来自真实计算，不依赖大模型生成" />

    <el-card shadow="never" class="config-card">
      <el-form label-width="100px">
        <el-form-item label="分析名称"><el-input v-model="form.name" placeholder="例如：工艺参数优化数据综合分析" /></el-form-item>
        <el-form-item label="选择数据集">
          <el-select v-model="form.dataset_id" filterable clearable placeholder="输入数据集 ID 或名称搜索" style="width:100%" @change="loadColumns">
            <el-option v-for="dataset in datasets" :key="dataset.id" :label="`#${dataset.id} ${dataset.name}（${dataset.row_count || 0} 行）`" :value="dataset.id" />
          </el-select>
        </el-form-item>
        <el-form-item :label="`分析项目（${algorithms.length}项）`" class="analysis-project-form-item">
          <div class="analysis-projects">
            <div class="analysis-project-toolbar">
              <span></span>
              <div>
                <el-input v-model="algorithmSearch" clearable placeholder="搜索分析名称或算法" style="width:230px" />
                <el-button v-if="form.analyses.length" link type="primary" @click="form.analyses=[]">清空已选（{{ form.analyses.length }}）</el-button>
              </div>
            </div>
            <el-table :data="filteredAlgorithms" border size="small" empty-text="没有匹配的分析项目">
              <el-table-column label="分析项目" min-width="180">
                <template #default="{row}"><b>{{ row.name }}</b><small class="analysis-project-algorithm">{{ row.algorithm }}</small></template>
              </el-table-column>
              <el-table-column label="功能说明" min-width="440"><template #default="{row}"><span class="analysis-project-guide">{{ guideText(row.id, row.description) }}</span></template></el-table-column>
              <el-table-column label="具体操作" width="210" fixed="right">
                <template #default="{row}">
                  <el-checkbox :model-value="form.analyses.includes(row.id)" @change="toggleAlgorithm(row.id, $event)">{{ form.analyses.includes(row.id) ? '已选择' : '选择分析' }}</el-checkbox>
                  <template v-if="parameterFields(row.id).length">
                    <el-button link type="primary" @click="openParameterDialog(row)">{{ parameterConfigured(row.id) ? '修改参数' : '设置参数' }}</el-button>
                    <span v-if="parameterConfigured(row.id)" class="parameter-saved">已保存：{{ parameterSummary(row.id) }}</span>
                  </template>
                  <span v-else class="fixed-parameter">固定口径</span>
                </template>
              </el-table-column>
            </el-table>
          </div>
        </el-form-item>
        <el-form-item label="数值字段" v-if="columns.numeric_columns.length">
          <el-select v-model="form.numeric_columns" multiple collapse-tags collapse-tags-tooltip clearable placeholder="默认分析全部数值字段（最多100列）" style="width:100%">
            <el-option v-for="column in columns.numeric_columns" :key="column" :label="column" :value="column" />
          </el-select>
        </el-form-item>
        <el-row :gutter="16" v-if="form.dataset_id">
          <el-col :span="12"><el-form-item label="时间变量 T"><el-select v-model="form.time_column" clearable filterable placeholder="时序分析使用；系统可自动识别" style="width:100%"><el-option v-for="column in columns.columns" :key="column" :label="column" :value="column" /></el-select></el-form-item></el-col>
          <el-col :span="12"><el-form-item label="因变量 Y"><el-select v-model="form.target_column" clearable filterable placeholder="希望解释或重点观察的目标；纯探索分析可不选" style="width:100%"><el-option v-for="column in columns.numeric_columns" :key="column" :label="column" :value="column" /></el-select></el-form-item></el-col>
        </el-row>
        <el-form-item v-if="form.dataset_id" label="分析时间范围">
          <el-date-picker v-model="form.time_range" type="datetimerange" value-format="YYYY-MM-DD HH:mm:ss" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间" clearable style="width:100%" />
          <div class="field-help">不填写则使用整个数据集；填写后，所有已选择的分析都只使用该时间范围内的数据。</div>
        </el-form-item>
        <el-form-item v-if="form.dataset_id" label="变量说明">
          <div class="variable-grid">
            <div class="variable-card target"><span class="variable-symbol">Y</span><div><b>因变量（分析目标）</b><p>{{ form.target_column || '未指定：探索分析仍可运行' }}</p></div></div>
            <div class="variable-card feature"><span class="variable-symbol">X</span><div><b>自变量（输入特征）</b><p>{{ featureColumns.length ? featureColumns.join('、') : '尚无可用数值特征' }}</p></div></div>
            <div class="variable-card time"><span class="variable-symbol">T</span><div><b>时间变量</b><p>{{ form.time_column || '未指定：只影响时序专项分析' }}</p></div></div>
            <div class="variable-card excluded"><span class="variable-symbol">—</span><div><b>未参与数值计算</b><p>{{ excludedColumns.length ? excludedColumns.join('、') : '无' }}</p></div></div>
          </div>
        </el-form-item>
      </el-form>
      <el-alert v-if="needsTime && !form.time_column" type="info" :closable="false" title="已选择时序专项分析。系统会尝试自动识别时间列；也可以手动指定。" />
      <div class="actions"><el-button v-if="userStore.hasPermission('datasets:analyze')" type="primary" size="large" :loading="running" @click="runAnalysis">开始分析</el-button><span v-if="columns.row_count">数据集共 {{ columns.row_count.toLocaleString() }} 行，识别到 {{ columns.numeric_columns.length }} 个数值字段</span></div>
      <el-progress v-if="running" :percentage="progress" striped striped-flow />
    </el-card>

    <el-dialog v-model="parameterDialog.visible" :title="`${parameterDialog.name} · 参数设置`" width="520px" destroy-on-close>
      <el-alert type="info" :closable="false" :title="parameterHelp[parameterDialog.id] || '该算法使用固定计算口径，无需额外参数。'" />
      <el-form v-if="parameterFields(parameterDialog.id).length" label-width="150px" class="parameter-form">
        <el-form-item v-for="field in parameterFields(parameterDialog.id)" :key="field.key" :label="field.label">
          <el-select v-if="field.type==='select'" v-model="parameterDraft[field.key]" style="width:100%"><el-option v-for="option in field.options" :key="option.value" :label="option.label" :value="option.value" /></el-select>
          <el-select v-else-if="field.type==='numeric-column'" v-model="parameterDraft[field.key]" clearable filterable style="width:100%" placeholder="不选则仅按时间连续性切分"><el-option v-for="column in columns.numeric_columns" :key="column" :label="column" :value="column" /></el-select>
          <el-select v-else-if="field.type==='numeric-columns'" v-model="parameterDraft[field.key]" multiple collapse-tags collapse-tags-tooltip clearable filterable style="width:100%" placeholder="请选择数值字段"><el-option v-for="column in columns.numeric_columns" :key="column" :label="column" :value="column" /></el-select>
          <el-switch v-else-if="field.type==='switch'" v-model="parameterDraft[field.key]" />
          <el-input-number v-else v-model="parameterDraft[field.key]" :min="field.min" :max="field.max" :step="field.step || 1" style="width:100%" />
          <div class="field-help">{{ field.help }}</div>
        </el-form-item>
      </el-form>
      <template #footer><el-button @click="resetParameterDraft">恢复默认</el-button><el-button type="primary" @click="saveParameterDialog">保存参数</el-button></template>
    </el-dialog>

    <template v-if="result">
      <div class="summary-grid">
        <div><span>数据集</span><strong>#{{ current?.dataset_id }} {{ result.source_name }}</strong></div>
        <div><span>分析行数</span><strong>{{ result.analyzed_rows?.toLocaleString() }}</strong></div>
        <div><span>数值字段</span><strong>{{ result.numeric_columns?.length }}</strong></div>
        <div><span>识别时间列</span><strong>{{ result.time_column || '无' }}</strong></div>
        <div v-if="result.time_range?.applied"><span>分析范围</span><strong>{{ result.time_range.start_time || '开始' }} 至 {{ result.time_range.end_time || '结束' }}（{{ result.time_range.analyzed_rows?.toLocaleString() }} 行）</strong></div>
      </div>
      <el-card v-if="savedParameterRows.length" shadow="never" class="saved-parameters-card">
        <template #header><div class="header"><span>本次已生效的参数配置</span><el-tag type="success">随分析记录保存</el-tag></div></template>
        <el-table :data="savedParameterRows" stripe size="small"><el-table-column prop="name" label="分析项目" min-width="220"/><el-table-column prop="summary" label="实际配置" min-width="420"/></el-table>
      </el-card>
      <el-card v-if="result.validation" shadow="never" class="validation-card">
        <template #header><div class="header"><span>独立基准核对</span><el-tag :type="result.validation.failed_count ? 'danger' : 'success'">{{ result.validation.passed_count }}/{{ result.validation.total_count }} 项通过</el-tag></div></template>
        <el-alert type="info" :closable="false" :title="result.validation.summary" style="margin-bottom:12px" />
        <el-table :data="result.validation.items" stripe max-height="420"><el-table-column prop="analysis" label="分析项目" min-width="190"/><el-table-column prop="method" label="核对方式" min-width="210"/><el-table-column label="结果" width="100"><template #default="{row}"><el-tag :type="row.status==='passed'?'success':'danger'">{{ row.status==='passed'?'通过':'未通过' }}</el-tag></template></el-table-column><el-table-column prop="detail" label="核对说明" min-width="420"/></el-table>
      </el-card>
      <el-card shadow="never" class="variables-result-card">
        <template #header><div class="header"><span>本次分析的变量角色</span><el-tag type="info">本次配置角色，不代表固定因果关系</el-tag></div></template>
        <div class="variable-grid result-variables">
          <div class="variable-card target"><span class="variable-symbol">Y</span><div><b>因变量</b><p>{{ result.variable_roles?.dependent || '未指定' }}</p></div></div>
          <div class="variable-card feature"><span class="variable-symbol">X</span><div><b>自变量 · {{ result.variable_roles?.independent?.length || 0 }} 个</b><p>{{ result.variable_roles?.independent?.join('、') || '无' }}</p></div></div>
          <div class="variable-card time"><span class="variable-symbol">T</span><div><b>时间变量</b><p>{{ result.variable_roles?.time || '未指定' }}</p></div></div>
          <div class="variable-card excluded"><span class="variable-symbol">—</span><div><b>未参与字段 · {{ result.variable_roles?.excluded?.length || 0 }} 个</b><p>{{ result.variable_roles?.excluded?.join('、') || '无' }}</p></div></div>
        </div>
      </el-card>
      <el-card shadow="never" class="result-card">
        <template #header><div class="header"><span>分析结果</span><el-button @click="downloadReport">下载 JSON 报告</el-button></div></template>
        <el-tabs v-model="activeResult" @tab-change="renderActiveChart">
          <el-tab-pane v-if="analysis.sensor_health" label="仪表健康" name="sensor_health" lazy>
            <Unavailable :value="analysis.sensor_health"/>
            <template v-if="analysis.sensor_health.available"><el-alert type="info" :closable="false" :title="analysis.sensor_health.note" style="margin-bottom:12px"/><el-table :data="analysis.sensor_health.items" stripe max-height="420"><el-table-column prop="column" label="字段" min-width="180"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.health==='good'?'success':'warning'">{{ row.health==='good'?'正常':'需检查' }}</el-tag></template></el-table-column><el-table-column prop="freeze_count" label="冻结段数"/><el-table-column prop="freeze_points" label="冻结点数"/><el-table-column prop="jump_count" label="异常跳变"/><el-table-column prop="jump_limit" label="跳变阈值"/></el-table></template>
          </el-tab-pane>
          <el-tab-pane v-if="analysis.operating_segments" label="运行段划分" name="operating_segments" lazy>
            <Unavailable :value="analysis.operating_segments"/>
            <template v-if="analysis.operating_segments.available"><el-alert type="info" :closable="false" :title="analysis.operating_segments.note" style="margin-bottom:12px"/><div class="mini-stats"><span>运行段 <b>{{ analysis.operating_segments.segment_count }}</b></span><span>断点阈值 <b>{{ analysis.operating_segments.gap_threshold_seconds }} 秒</b></span><span v-if="analysis.operating_segments.condition?.column">工况字段 <b>{{ analysis.operating_segments.condition.column }}</b></span><span v-if="analysis.operating_segments.condition?.column">符合工况 <b>{{ analysis.operating_segments.eligible_rows }}</b> 行</span></div><el-table :data="analysis.operating_segments.segments" stripe max-height="420"><el-table-column prop="segment_id" label="段 ID" width="90"/><el-table-column prop="start_time" label="开始时间" min-width="180"/><el-table-column prop="end_time" label="结束时间" min-width="180"/><el-table-column prop="points" label="点数"/><el-table-column prop="duration_label" label="持续时间"/><el-table-column prop="complete_row_rate" label="完整行率(%)"/><el-table-column v-if="analysis.operating_segments.condition?.column" label="工况范围" min-width="150"><template #default="{row}">{{ row.condition_min_value }} ～ {{ row.condition_max_value }}</template></el-table-column><el-table-column label="可用"><template #default="{row}"><el-tag :type="row.meets_minimum_points?'success':'warning'">{{ row.meets_minimum_points?'可用':'过短' }}</el-tag></template></el-table-column><el-table-column v-if="userStore.hasPermission('datasets:upload')" label="操作" width="130"><template #default="{row}"><el-button link type="primary" :disabled="!row.meets_minimum_points" @click="saveSegmentAsDataset(row)">保存为数据集</el-button></template></el-table-column></el-table></template>
          </el-tab-pane>
          <el-tab-pane v-if="analysis.window_quality" label="窗口质量" name="window_quality" lazy>
            <Unavailable :value="analysis.window_quality"/>
            <template v-if="analysis.window_quality.available"><el-alert type="info" :closable="false" :title="analysis.window_quality.note" style="margin-bottom:12px"/><div class="mini-stats"><span>窗口长度 <b>{{ analysis.window_quality.window_seconds }} 秒</b></span><span>通过窗口 <b>{{ analysis.window_quality.passed_windows }}/{{ analysis.window_quality.total_windows }}</b></span><span>通过率 <b>{{ analysis.window_quality.pass_rate }}%</b></span></div><el-table :data="analysis.window_quality.failed_examples" stripe max-height="420"><el-table-column prop="start_time" label="窗口开始" min-width="190"/><el-table-column prop="points" label="点数"/><el-table-column prop="observed_ratio" label="点数覆盖率(%)"/><el-table-column prop="complete_row_ratio" label="完整行率(%)"/><el-table-column prop="frozen_columns" label="冻结字段" min-width="180"><template #default="{row}">{{ row.frozen_columns?.join('、')||'-' }}</template></el-table-column><el-table-column prop="reasons" label="未通过原因" min-width="180"><template #default="{row}">{{ row.reasons?.join('、') }}</template></el-table-column></el-table></template>
          </el-tab-pane>
          <el-tab-pane v-if="analysis.hampel" label="局部尖峰（Hampel）" name="hampel" lazy>
            <Unavailable :value="analysis.hampel"/>
            <template v-if="analysis.hampel.available"><el-alert type="info" :closable="false" :title="`${analysis.hampel.note} 窗口=${analysis.hampel.window}点，MAD阈值=${analysis.hampel.threshold}。`" style="margin-bottom:12px"/><el-table :data="analysis.hampel.items" stripe max-height="260"><el-table-column prop="column" label="字段" min-width="200"/><el-table-column prop="count" label="尖峰数"/><el-table-column prop="rate" label="尖峰率(%)"/><el-table-column label="样例数"><template #default="{row}">{{ row.points?.length||0 }}</template></el-table-column></el-table><el-table :data="hampelRows" stripe max-height="320" style="margin-top:12px"><el-table-column prop="time" label="尖峰时间" min-width="190"/><el-table-column prop="row" label="行号"/><el-table-column prop="column" label="字段"/><el-table-column prop="value" label="实际值"/><el-table-column prop="local_median" label="局部中位数"/></el-table></template>
          </el-tab-pane>
          <el-tab-pane v-if="analysis.effective_excitation" label="有效激励" name="effective_excitation" lazy>
            <Unavailable :value="analysis.effective_excitation"/>
            <template v-if="analysis.effective_excitation.available"><el-alert type="info" :closable="false" :title="analysis.effective_excitation.note" style="margin-bottom:12px"/><div class="mini-stats"><span>满足条件字段 <b>{{ analysis.effective_excitation.adequate_count }}</b></span><span>最低变化覆盖率 <b>{{ analysis.effective_excitation.minimum_active_ratio*100 }}%</b></span></div><el-table :data="analysis.effective_excitation.items" stripe max-height="420"><el-table-column prop="column" label="输入字段" min-width="210"/><el-table-column label="结论"><template #default="{row}"><el-tag :type="row.status==='adequate'?'success':'warning'">{{ row.status==='adequate'?'变化充分':'变化不足' }}</el-tag></template></el-table-column><el-table-column prop="active_ratio" label="变化覆盖率(%)"/><el-table-column prop="event_count" label="变化事件数"/><el-table-column prop="robust_range" label="稳健变化范围"/><el-table-column prop="unique_values" label="唯一值数"/></el-table></template>
          </el-tab-pane>
          <el-tab-pane v-if="analysis.overview" label="数据概况（描述性统计）" name="overview" lazy>
            <div class="mini-stats"><span>总行数 <b>{{ analysis.overview.total_rows?.toLocaleString() }}</b></span><span>字段数 <b>{{ analysis.overview.total_columns }}</b></span><span>缺失率 <b>{{ analysis.overview.missing_rate }}%</b></span><span>重复行 <b>{{ analysis.overview.duplicate_rows }}</b></span></div>
            <el-table :data="analysis.overview.columns" stripe max-height="420"><el-table-column prop="name" label="字段" min-width="180" show-overflow-tooltip/><el-table-column prop="kind" label="类型" width="100"/><el-table-column prop="missing_rate" label="缺失率(%)" width="110"/><el-table-column prop="unique_count" label="唯一值" width="100"/><el-table-column label="均值" width="120"><template #default="{row}">{{ row.statistics?.mean ?? '-' }}</template></el-table-column><el-table-column label="标准差" width="120"><template #default="{row}">{{ row.statistics?.std ?? '-' }}</template></el-table-column></el-table>
          </el-tab-pane>
          <el-tab-pane v-if="analysis.time_quality" label="时间轴质量（完整性+对齐）" name="time_quality" lazy>
            <Unavailable :value="analysis.time_quality"/>
            <template v-if="analysis.time_quality.available">
              <el-alert
                :type="analysis.time_quality.status==='good'?'success':analysis.time_quality.status==='warning'?'warning':'error'"
                :closable="false"
                :title="analysis.time_quality.issues?.length ? analysis.time_quality.issues.join('；') : '时间轴完整且顺序正常'"
                style="margin-bottom:14px"
              />
              <div class="mini-stats">
                <span>典型采样间隔 <b>{{ analysis.time_quality.sample_interval_label }}</b></span>
                <span>时间覆盖率 <b>{{ analysis.time_quality.coverage_rate }}%</b></span>
                <span>缺失时间点 <b>{{ analysis.time_quality.missing_time_points }}</b></span>
                <span>最长缺口 <b>{{ analysis.time_quality.max_gap_label }}</b></span>
                <span>时间倒序 <b>{{ analysis.time_quality.backward_jumps }}</b></span>
              </div>
              <el-tabs type="border-card">
                <el-tab-pane label="采样间隔分布"><el-table :data="analysis.time_quality.interval_distribution" max-height="320"><el-table-column prop="label" label="间隔"/><el-table-column prop="seconds" label="秒数"/><el-table-column prop="count" label="出现次数"/></el-table></el-tab-pane>
                <el-tab-pane :label="`缺口定位（${analysis.time_quality.gap_count || 0}）`"><div class="table-toolbar"><span>列出超过典型采样间隔 1.5 倍的缺口，便于回查源数据。</span><el-button :disabled="!analysis.time_quality.gap_examples?.length" @click="downloadTimeGaps">下载缺口清单</el-button></div><el-table :data="analysis.time_quality.gap_examples" max-height="320"><el-table-column prop="before_time" label="缺口前时间" min-width="185"/><el-table-column prop="after_time" label="缺口后时间" min-width="185"/><el-table-column prop="gap_label" label="缺口时长"/><el-table-column prop="estimated_missing_points" label="估计缺失点数"/><el-table-column prop="kind" label="类型"/></el-table><el-empty v-if="!analysis.time_quality.gap_examples?.length" description="未发现明显采样缺口"/></el-tab-pane>
                <el-tab-pane label="时间列对齐"><el-table :data="analysis.time_quality.time_offsets" max-height="320"><el-table-column prop="column" label="其他时间列" min-width="180"/><el-table-column prop="median_label" label="相对偏移"/><el-table-column prop="valid_pairs" label="有效配对"/><el-table-column label="是否固定"><template #default="{row}"><el-tag :type="row.is_constant?'success':'warning'">{{ row.is_constant?'固定':'有波动' }}</el-tag></template></el-table-column></el-table><el-empty v-if="!analysis.time_quality.time_offsets?.length" description="没有识别到其他可对齐时间列"/></el-tab-pane>
              </el-tabs>
            </template>
          </el-tab-pane>
          <el-tab-pane v-if="analysis.distribution" label="分布分析（直方图+箱线统计）" name="distribution" lazy>
            <el-select v-model="distributionColumn" @change="renderActiveChart" style="width:300px;margin-bottom:12px"><el-option v-for="item in analysis.distribution.items" :key="item.column" :label="item.column" :value="item.column"/></el-select>
            <div ref="mainChart" class="chart" />
            <el-descriptions v-if="selectedDistribution" :column="5" border><el-descriptions-item v-for="(value,key) in selectedDistribution.statistics" :key="key" :label="statLabel(key)">{{ value }}</el-descriptions-item></el-descriptions>
          </el-tab-pane>
          <el-tab-pane v-if="analysis.correlation" label="相关性（Pearson+Spearman）" name="correlation" lazy>
            <el-radio-group v-model="correlationMethod" @change="renderActiveChart"><el-radio-button value="pearson">Pearson</el-radio-button><el-radio-button value="spearman">Spearman</el-radio-button></el-radio-group><div ref="mainChart" class="chart tall"/>
          </el-tab-pane>
          <el-tab-pane v-if="analysis.sensor_consistency" label="多雷达一致性" name="sensor_consistency" lazy>
            <Unavailable :value="analysis.sensor_consistency"/>
            <template v-if="analysis.sensor_consistency.available">
              <el-alert type="info" :closable="false" :title="analysis.sensor_consistency.note" style="margin-bottom:12px"/>
