            <template v-if="analysis.time_drift.available">
              <div class="anomaly-methods"><div><span>分布稳定 · PSI&lt;0.1</span><b>{{ analysis.time_drift.summary.stable }}</b><small>字段</small></div><div><span>需要关注 · PSI 0.1~0.25</span><b>{{ analysis.time_drift.summary.warning }}</b><small>字段</small></div><div><span>显著漂移 · PSI≥0.25</span><b>{{ analysis.time_drift.summary.significant }}</b><small>字段</small></div></div>
              <div ref="mainChart" class="chart tall"/>
              <el-table :data="analysis.time_drift.items" max-height="380"><el-table-column prop="column" label="字段" min-width="220"/><el-table-column label="漂移等级"><template #default="{row}"><el-tag :type="driftTagType(row.level)">{{ driftLevelLabel(row.level) }}</el-tag></template></el-table-column><el-table-column prop="psi" label="PSI"/><el-table-column prop="ks_statistic" label="KS统计量"/><el-table-column prop="ks_p_value" label="KS p值"/><el-table-column prop="normalized_wasserstein" label="标准化距离"/><el-table-column prop="mean_change" label="均值变化"/></el-table>
            </template>
          </el-tab-pane>
        </el-tabs>
      </el-card>
    </template>

    <el-card shadow="never" class="history-card"><template #header><div class="header"><span>历史分析记录</span><el-button text type="primary" @click="loadHistory">刷新</el-button></div></template><el-table :data="history" stripe><el-table-column prop="id" label="记录ID" width="90"/><el-table-column prop="name" label="分析名称" min-width="180"/><el-table-column prop="dataset_id" label="数据集ID" width="100"/><el-table-column prop="dataset_name" label="数据集" min-width="180"/><el-table-column label="分析项" min-width="240"><template #default="{row}">{{ algorithmNames(row.configuration?.analyses) }}</template></el-table-column><el-table-column prop="created_at" label="创建时间" width="180"><template #default="{row}">{{ formatDate(row.created_at) }}</template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" :loading="openingRunId===row.id" :disabled="openingRunId!==null" @click="openRun(row.id)">查看</el-button><el-button v-if="userStore.hasPermission('datasets:analyze')" link type="danger" @click="removeRun(row)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!history.length" description="暂无分析记录"/></el-card>
  </div>
</template>

<script setup lang="ts">
import { computed, defineComponent, h, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { ElAlert, ElMessage, ElMessageBox } from 'element-plus'
import * as echarts from 'echarts'
import PageHeader from '@/components/PageHeader.vue'
import { useUserStore } from '@/stores/user'
import { del, get, post, put } from '@/api/legacy'

const userStore = useUserStore()
const Unavailable=defineComponent({props:{value:{type:Object,required:true}},setup(props){return()=>!props.value.available?h(ElAlert,{type:'info',closable:false,title:props.value.reason||'当前数据不满足该分析条件',style:'margin-bottom:12px'}):null}})
const algorithms=ref<any[]>([]),datasets=ref<any[]>([]),history=ref<any[]>([])
const algorithmSearch=ref('')
const PARAMETER_STORAGE_PREFIX='foundation:data-analysis:parameters:'
const columns=ref<any>({columns:[],numeric_columns:[],row_count:0})
const form=ref<any>({name:'数据综合分析',dataset_id:null,analyses:['overview','time_quality','sensor_health','operating_segments','window_quality','hampel','effective_excitation','anomaly','trend','correlation'],numeric_columns:[],time_column:null,target_column:null,time_range:[],algorithm_params:{}})
const current=ref<any>(null),running=ref(false),progress=ref(0),activeResult=ref('overview'),openingRunId=ref<number|null>(null),operationImpactAi=ref<any>(null),operationImpactAiLoading=ref(false)
const mainChart=ref<HTMLElement>(),secondChart=ref<HTMLElement>();let charts:echarts.ECharts[]=[];let timer:number|undefined
const result=computed(()=>current.value?.result||null),analysis=computed(()=>result.value?.analyses||{})
const needsTime=computed(()=>form.value.analyses.some((item:string)=>['time_quality','trend','lag','change_point','acf_pacf','cross_correlation','spectrum','filtering','time_drift','hampel','sensor_health','operating_segments','window_quality','effective_excitation','dynamic_regression','operation_impact'].includes(item)))
const selectedAlgorithms=computed<any[]>(()=>algorithms.value.filter((item:any)=>form.value.analyses.includes(item.id)))
const savedParameterRows=computed(()=>Object.entries(current.value?.configuration?.algorithm_params||{}).filter(([,value])=>value&&Object.keys(value as object).length).map(([id,value])=>({name:algorithms.value.find((item:any)=>item.id===id)?.name||id,summary:parameterSummary(id,value as Record<string,any>)})))
const filteredAlgorithms=computed<any[]>(()=>{const key=algorithmSearch.value.trim().toLowerCase();return key?algorithms.value.filter((item:any)=>`${item.name||''} ${item.algorithm||''} ${item.description||''}`.toLowerCase().includes(key)):algorithms.value})
const selectedNumericColumns=computed<string[]>(()=>form.value.numeric_columns.length?form.value.numeric_columns:columns.value.numeric_columns)
const featureColumns=computed<string[]>(()=>selectedNumericColumns.value.filter(column=>column!==form.value.target_column))
const excludedColumns=computed<string[]>(()=>columns.value.columns.filter((column:string)=>!selectedNumericColumns.value.includes(column)&&column!==form.value.time_column&&column!==form.value.target_column))
const distributionColumn=ref(''),normalityColumn=ref(''),crossCorrelationColumn=ref(''),correlationMethod=ref<'pearson'|'spearman'>('pearson')
const selectedDistribution=computed(()=>analysis.value.distribution?.items?.find((item:any)=>item.column===distributionColumn.value))
const selectedNormality=computed(()=>analysis.value.normality?.items?.find((item:any)=>item.column===normalityColumn.value))
const selectedCrossCorrelation=computed(()=>analysis.value.cross_correlation?.items?.find((item:any)=>item.column===crossCorrelationColumn.value))
const changePointRows=computed(()=>analysis.value.change_point?.items?.flatMap((item:any)=>item.points.map((point:any)=>({column:item.column,...point})))||[])
const hampelRows=computed(()=>analysis.value.hampel?.items?.flatMap((item:any)=>item.points.map((point:any)=>({column:item.column,...point})))||[])
const parameterDialog=ref({visible:false,id:'',name:''}),parameterDraft=ref<any>({})
const parameterDefaults:Record<string,any>={overview:{},time_quality:{},distribution:{bins:0},correlation:{},cca:{x_columns:[],y_columns:[],components:3,sample_size:20000},sensor_consistency:{sensor_columns:[],reference_method:'median',threshold:3},operation_impact:{operation_column:null,response_columns:[],change_threshold:.02,pre_window_seconds:60,post_window_seconds:300,minimum_event_gap_seconds:60,max_lag:60,resample_interval_seconds:0,interpolation_limit:3},dynamic_regression:{driver_columns:[],max_lag:12,alpha:1,test_fraction:.2,resample_interval_seconds:0,interpolation_limit:3,include_target_history:true},mutual_information:{neighbors:3,sample_size:20000},anomaly:{iqr_multiplier:1.5,sigma_multiplier:3,threshold_sigma:5,estimators:100},trend:{window:0},lag:{max_lag:24,resample_interval_seconds:0,interpolation_limit:3},change_point:{window:0,threshold_sigma:3},pca:{components:5},normality:{alpha:0.05,sample_size:5000},acf_pacf:{max_lag:24},cross_correlation:{max_lag:24,resample_interval_seconds:0,interpolation_limit:3},spectrum:{resample_interval_seconds:0,detrend:true},filtering:{method:'moving_average',window:5,cutoff_ratio:0.1,order:4},time_drift:{window_fraction:0.3,alpha:0.05,psi_bins:10}}
const parameterHelp:Record<string,string>={overview:'按完整字段计算行列规模、缺失率、重复率和描述性统计。',time_quality:'固定检查时间顺序、重复时间、缺失时间点、采样间隔与其他时间列偏移。',distribution:'设置直方图分组数量；0表示根据样本量自动计算。',correlation:'固定同时计算 Pearson 线性相关和 Spearman 单调相关。',cca:'分别选择 X 与 Y 两组数值字段，平台会标准化后计算各典型变量对的综合关联。Y 组只有一个字段时，结果代表 X 组对该字段的综合关联。',sensor_consistency:'选择至少三台测量同一工况的传感器。平台会把每台传感器与其余传感器形成的中位数或均值参考值比较。',operation_impact:'选择一个现场操作变量和一个或多个响应字段。平台会筛选变更前稳定的操作事件，叠加响应曲线、进行分布滞后验证，并列出操作区间统计；它提供统计证据，不直接证明因果。',dynamic_regression:'先选择页面上的目标列，再选择操作/输入字段。模型按时间前段训练、后段测试，输出不同滞后时刻的统计解释强度。',mutual_information:'近邻数越大结果越平滑；分数用于特征间相对排序，不代表因果关系。',anomaly:'IQR适合偏态数据，3σ适合近似正态分布字段，Isolation Forest用于多字段联合异常。',trend:'设置移动平均窗口；0表示系统根据数据量自动选择。',lag:'先按时间轴重采样，再计算特征领先目标的滞后关系；插值上限用于避免跨越长缺口。',change_point:'窗口决定比较尺度，σ阈值越小越敏感；0窗口表示自动。',pca:'设置最多输出的主成分数量，实际数量不会超过有效字段数。',normality:'显著性水平决定拒绝正态假设的阈值；样本过大时进行等距抽样。',acf_pacf:'设置目标序列自相关和偏自相关的最大滞后阶数。',cross_correlation:'先按时间轴重采样，再向前、向后搜索互相关。',spectrum:'不等间隔数据会重采样；0秒表示使用时间列的中位采样间隔。',filtering:'选择滤波算法及对应窗口/截止频率；Butterworth阶数只对低通滤波生效。',time_drift:'取时间轴前后两个窗口比较字段分布；PSI≥0.25视为显著漂移。',hampel:"窗口越大越平滑；阈值越小越敏感，适合识别局部尖峰。",sensor_health:"冻结点数是判定连续死值的最小长度；跳变阈值按鲁棒变化率计算。",operating_segments:"超过断点阈值即切分运行段；0表示按典型采样间隔的3倍自动判断。",window_quality:"按固定时间窗口复核点数、完整行率和冻结字段。",effective_excitation:"变化覆盖率越高，说明信号中可用于动态建模的有效变化越充分。"}
const parameterFieldMap:Record<string,any[]>={operation_impact:[{key:'operation_column',label:'操作变量',type:'numeric-column',help:'例如圆辊给矿机转速系数；每次变更将作为候选操作事件'},{key:'response_columns',label:'响应字段',type:'numeric-columns',help:'选择需要比较的料层、质量或其他过程响应；最多 12 个'},{key:'change_threshold',label:'最小操作变更量',min:.000001,max:1000000,step:.01,help:'相邻操作值变化达到此幅度才认定为一次操作变更；建议先按实际最小调节档位填写'},{key:'pre_window_seconds',label:'变更前稳定窗口（秒）',min:5,max:3600,step:5,help:'该窗口内出现其他同等级变更的记录会排除，避免混入连续操作'},{key:'post_window_seconds',label:'最大观察窗口（秒）',min:5,max:3600,step:5,help:'每次操作后最多观察多久的响应；后续再次操作会截短该事件'},{key:'minimum_event_gap_seconds',label:'事件最小间隔（秒）',min:0,max:3600,step:5,help:'避免把同一轮连续调整重复计入多个事件'},{key:'max_lag',label:'滞后验证最大步数',min:1,max:120,help:'用于分布滞后回归；与采样间隔相乘为最大回看时长'},{key:'resample_interval_seconds',label:'重采样间隔（秒）',min:0,max:86400,help:'0=自动识别典型采样间隔'},{key:'interpolation_limit',label:'连续插值上限',min:0,max:48,help:'超过该步数的缺口不插值'}],sensor_consistency:[{key:'sensor_columns',label:'同类雷达字段',type:'numeric-columns',help:'至少选择 3 个测量同一对象的雷达/传感器'},{key:'reference_method',label:'参考值方式',type:'select',options:[{label:'其余雷达中位数（推荐）',value:'median'},{label:'其余雷达均值',value:'mean'}],help:'中位数更不容易受单个异常雷达影响'},{key:'threshold',label:'异常偏差阈值σ',min:1,max:10,step:.5,help:'默认 3σ，越小越敏感'}],dynamic_regression:[{key:'driver_columns',label:'操作/输入字段',type:'numeric-columns',help:'例如圆辊给矿机转速系数；最多选择 12 个'},{key:'max_lag',label:'最大回看步数',min:1,max:120,help:'会同时使用当前与过去多个时刻的输入值'},{key:'alpha',label:'岭回归正则强度',min:.000001,max:1000,step:.1,help:'默认1；字段高度相关时可提高以增强稳定性'},{key:'test_fraction',label:'后段测试占比',min:.1,max:.4,step:.05,help:'默认20%，保留时间后段做独立检验'},{key:'resample_interval_seconds',label:'重采样间隔（秒）',min:0,max:86400,help:'0=自动识别典型采样间隔'},{key:'interpolation_limit',label:'连续插值上限',min:0,max:48,help:'超过该步数的缺口不插值'},{key:'include_target_history',label:'纳入目标历史值',type:'switch',help:'建议开启，用于判断操作变量的额外解释能力'}],cca:[{key:'x_columns',label:'X 变量组',type:'numeric-columns',help:'至少选择一个数值字段，例如多个雷达料位计'},{key:'y_columns',label:'Y 变量组',type:'numeric-columns',help:'至少选择一个数值字段，例如现场操作值或多个质量指标'},{key:'components',label:'典型变量对数量',min:1,max:20,help:'不超过两组中较小的字段数'},{key:'sample_size',label:'最大样本数',min:100,max:100000,step:100,help:'数据过大时固定随机抽样'}],distribution:[{key:'bins',label:'直方图分组数',min:0,max:100,help:'0=自动，手动建议10～50'}],mutual_information:[{key:'neighbors',label:'近邻数量',min:2,max:20,help:'默认3，越大越平滑'},{key:'sample_size',label:'最大样本数',min:100,max:100000,step:100,help:'数据过大时固定随机抽样'}],anomaly:[{key:'iqr_multiplier',label:'IQR倍数',min:.5,max:5,step:.1,help:'越小越敏感，默认1.5'},{key:'sigma_multiplier',label:'3σ判定倍数',min:1,max:6,step:.5,help:'默认3，即均值±3倍标准差'},{key:'threshold_sigma',label:'森林分数σ阈值',min:1,max:10,step:.5,help:'仅用于Isolation Forest，默认5'},{key:'estimators',label:'Isolation Forest树数',min:50,max:500,step:50,help:'越大越稳定但计算更慢'}],trend:[{key:'window',label:'移动平均窗口',min:0,max:500,help:'0=自动'}],lag:[{key:'max_lag',label:'最大滞后步数',min:1,max:200,help:'基于重采样后间隔'},{key:'resample_interval_seconds',label:'重采样间隔（秒）',min:0,max:86400,help:'0=自动识别'},{key:'interpolation_limit',label:'连续插值上限',min:0,max:48,help:'超过该步数的缺口不插值'}],change_point:[{key:'window',label:'检测窗口',min:0,max:500,help:'0=自动'},{key:'threshold_sigma',label:'变化阈值σ',min:1,max:10,step:.5,help:'越小越敏感'}],pca:[{key:'components',label:'主成分数量',min:2,max:20,help:'最多输出数量'}],normality:[{key:'alpha',label:'显著性水平α',min:.001,max:.2,step:.001,help:'常用0.05'},{key:'sample_size',label:'最大检验样本数',min:50,max:5000,step:50,help:'最多5000'}],acf_pacf:[{key:'max_lag',label:'最大滞后阶数',min:1,max:200,help:'ACF/PACF阶数'}],cross_correlation:[{key:'max_lag',label:'双向最大滞后',min:1,max:200,help:'分别向前、向后搜索'},{key:'resample_interval_seconds',label:'重采样间隔（秒）',min:0,max:86400,help:'0=自动识别'},{key:'interpolation_limit',label:'连续插值上限',min:0,max:48,help:'超过该步数的缺口不插值'}],spectrum:[{key:'resample_interval_seconds',label:'重采样间隔（秒）',min:0,max:86400,step:1,help:'0=自动识别'},{key:'detrend',label:'去除线性趋势',type:'switch',help:'建议开启'}],filtering:[{key:'method',label:'滤波算法',type:'select',options:[{label:'滑动平均',value:'moving_average'},{label:'中值滤波',value:'median'},{label:'Butterworth低通',value:'butterworth'}],help:'选择滤波方法'},{key:'window',label:'滤波窗口',min:3,max:101,step:2,help:'滑动平均/中值滤波使用'},{key:'cutoff_ratio',label:'截止频率比',min:.01,max:.99,step:.01,help:'Butterworth使用'},{key:'order',label:'Butterworth阶数',min:1,max:10,help:'阶数越高截止越陡'}],time_drift:[{key:'window_fraction',label:'前后窗口比例',min:.1,max:.5,step:.05,help:'默认各取前后30%'},{key:'alpha',label:'KS显著性α',min:.001,max:.2,step:.001,help:'默认0.05'},{key:'psi_bins',label:'PSI分箱数',min:5,max:50,help:'默认10'}],hampel:[{key:"window",label:"局部窗口点数",min:3,max:101,step:2,help:"默认11；会自动调整为奇数"},{key:"threshold",label:"MAD阈值",min:1,max:10,step:.5,help:"默认3；越小越敏感"}],sensor_health:[{key:"freeze_points",label:"冻结判定点数",min:3,max:10000,help:"连续相同读数达到该点数即提示"},{key:"jump_sigma",label:"跳变阈值σ",min:1,max:20,step:.5,help:"基于鲁棒变化率"}],operating_segments:[{key:"gap_seconds",label:"断点阈值（秒）",min:0,max:86400,help:"0=典型采样间隔的3倍"},{key:"minimum_points",label:"最小段长度",min:2,max:100000,help:"低于此长度的段标记为过短"}],window_quality:[{key:"window_seconds",label:"窗口长度（秒）",min:1,max:86400,help:"常用60秒"},{key:"minimum_valid_ratio",label:"最低有效率",min:.05,max:1,step:.05,help:"默认50%"}],effective_excitation:[{key:"minimum_active_ratio",label:"最低变化覆盖率",min:.001,max:.95,step:.01,help:"默认5%"},{key:"change_fraction",label:"变化判定比例",min:.0001,max:1,step:.005,help:"相对稳健变化范围"}]}

const analysisGuides:Record<string,string>={
  overview:'快速了解数据规模、字段类型、缺失与重复情况，并查看均值、分位数等基础统计。它适合作为任何分析或建模前的第一步，不能代替对业务含义的判断。',
  distribution:'观察单个字段的数值分布、集中位置和离散程度，可用来发现偏态、长尾或明显离群值。直方图分组数会影响细节，不应只凭单张图下结论。',
  correlation:'同时计算线性相关（Pearson）与单调关系（Spearman），用于初步筛选可能有关联的字段。相关性不表示因果关系，且会受工况、时间趋势和异常值影响。',
  cca:'将 X 组与 Y 组字段分别组合，寻找两组整体关联最强的线性组合。它适合比较多台仪表与操作指标组的整体关系；若只需逐个字段的系数，请同时使用相关性分析。',
  sensor_consistency:'将每台雷达与其余雷达形成的参考值比较，识别长期偏差、波动偏差和短时孤立异常。它更适合发现与同类测点不一致的仪表读数，不能替代人工实测基准。',
  anomaly_attribution:'先分别找出多个目标字段的局部异常，再回看异常前的候选变量是否出现异常突变，并结合时间后段的分布滞后模型给出优先核查顺序。它能缩小排查范围，但没有纳入的工况和共同操作会造成混杂，因此不等同确定根因。',
  operation_impact:'以现场操作变量的离散变更为事件起点，叠加多个响应字段在变更后的走势，并用独立时间后段做分布滞后验证、用操作区间统计筛查非线性。适合回答“操作后是否常出现同向响应、多久出现、操作变量新增解释有多大”；没有纳入的工况会造成混杂，因此不能直接当作因果结论。',
  dynamic_regression:'把当前与过去多个时刻的操作值纳入同一模型，在独立的时间后段检验预测误差和增量解释能力。它可用于寻找可能的响应滞后，但不是因果证明。',
  anomaly:'使用 IQR、3σ 和 Isolation Forest 从单字段与多字段两个角度识别异常记录。结果是需要复核的提示，不应直接删除数据；3σ更适合近似正态的连续数据。',
  trend:'按时间展示原始走势和移动平均趋势，帮助识别缓慢上升、下降或阶段性变化。窗口越大趋势越平滑，也越容易掩盖短时波动。',
  lag:'比较输入字段在不同滞后时刻与目标的相关性，用于寻找可能的领先或滞后关系。时序数据会先按等间隔处理，结果不是因果证明。',
  change_point:'查找相邻时间窗口均值发生明显变化的位置，适合定位可能的工况切换。它只提示变化发生，实际原因仍需结合生产事件和工艺知识确认。',
  pca:'将多个相互关联的字段压缩成少量主成分，查看数据主要变化由哪些字段共同构成。平台会先标准化字段，主成分本身不等同于实际工艺变量。',
  normality:'通过 Shapiro-Wilk 检验和 QQ 图检查字段是否近似正态，用于判断是否适合重点参考3σ等方法。p值不是“正态证明”，应与图形、偏度和业务背景一起看。',
  acf_pacf:'检查一个目标序列与其过去值之间的依赖关系，帮助判断记忆长度和可能的时序特征窗口。平台会对缺失点插值，因此需先查看时间轴质量。',
  cross_correlation:'在输入字段与目标之间双向搜索时间滞后关系，适合发现谁可能先变化、谁可能后响应。必须先保证时间列可靠，强互相关也不等于因果。',
  spectrum:'将等间隔时序拆成不同频率成分，寻找重复出现的周期或振荡。采样率决定可识别的最高频率；不规则时间序列会先重采样。',
  filtering:'使用滑动平均、中值或 Butterworth 低通滤波减少高频噪声，并对比滤波前后曲线。滤波会改变信号细节，尤其是序列边界，应保留原始数据。',
  time_quality:'检查时间列是否乱序、重复、缺失或存在不规则间隔，并分析多个时间列的偏移。它决定后续时序分析是否可信，建议优先运行。',
  mutual_information:'用互信息发现线性相关不明显但仍可能存在的非线性依赖，并按强弱排序特征。分数没有正负方向，也不能解释为因果效应。',
  time_drift:'比较前后两个时间窗口的字段分布，识别可能的工况、原料或传感器变化。漂移表示分布不同，需再结合时间范围和生产背景寻找原因。',
  hampel:'用局部中位数和 MAD 识别短时尖峰，较少把缓慢的真实工况变化误判为异常。适合传感器瞬时跳点检查，窗口和阈值应按采样频率调整。',
  sensor_health:'检查传感器冻结、连续死值和异常突跳，给出仪表健康提示。它不包含设备物理上下限，具体工程判定仍应通过项目规则补充。',
  operating_segments:'根据时间断点划分独立连续运行段，并可叠加工况字段范围与突变条件，避免跨停机段或不同工况进行插值和时序计算。合格段可保存为新数据集。',
  window_quality:'按固定时间窗口检查点数覆盖率、完整行率和字段冻结情况，判断哪些窗口适合建模或聚合。阈值应结合实际采样频率和项目要求设置。',
  effective_excitation:'评估输入字段是否有足够的变化范围和变化频次，判断数据是否适合动态或时序建模。变化充分不代表一定能建立高精度模型，只是基本前提之一。',
}
function guideText(id:string,fallback:string){return analysisGuides[id]||fallback}

function parameterFields(id:string){return parameterFieldMap[id]||[]}
// 参数值均为数字/字符串/布尔;structuredClone 无法克隆 Vue 响应式 Proxy(抛 DataCloneError),故用 JSON 深拷贝
function cloneParams<T>(value:T):T{return value==null?value:JSON.parse(JSON.stringify(value))}
function removeAlgorithm(id:string){form.value.analyses=form.value.analyses.filter((item:string)=>item!==id)}
function toggleAlgorithm(id:string, selected:boolean){const current=form.value.analyses as string[];form.value.analyses=selected?(current.includes(id)?current:[...current,id]):current.filter(item=>item!==id)}
function openParameterDialog(item:any){parameterDialog.value={visible:true,id:item.id,name:item.name};parameterDraft.value=cloneParams(form.value.algorithm_params[item.id]||parameterDefaults[item.id]||{})}
function resetParameterDraft(){parameterDraft.value=cloneParams(parameterDefaults[parameterDialog.value.id]||{})}
function parameterConfigured(id:string){return Object.keys(form.value.algorithm_params?.[id]||{}).length>0}
async function saveParameterDialog(){const id=parameterDialog.value.id;form.value.algorithm_params={...form.value.algorithm_params,[id]:cloneParams(parameterDraft.value)};try{await persistParameterSettings();parameterDialog.value.visible=false;ElMessage.success(`${parameterDialog.value.name} 参数已保存，并会在下次选择该数据集时恢复`)}catch(e:any){ElMessage.error(e?.message||'参数保存失败，请重试')}}
function parameterSummary(id:string,configured?:Record<string,any>){const v=configured??(form.value.algorithm_params[id]||parameterDefaults[id]||{});if(!parameterFields(id).length)return '固定口径';const x:Record<string,any>={cca:`X ${v.x_columns?.length||0} 个 / Y ${v.y_columns?.length||0} 个 / ${v.components||1} 对`,sensor_consistency:`${v.sensor_columns?.length||0} 个雷达 / ${v.reference_method==='mean'?'均值':'中位数'}参考`,operation_impact:`操作 ${v.operation_column||'未选'} / 响应 ${v.response_columns?.length||0} 个 / 阈值 ${v.change_threshold??.02}`,dynamic_regression:`${v.driver_columns?.length||0} 个输入 / 回看 ${v.max_lag} 步`,distribution:v.bins?`${v.bins}组`:'自动分组',mutual_information:`近邻 ${v.neighbors}`,anomaly:`IQR ${v.iqr_multiplier} / ${v.sigma_multiplier}σ / IF ${v.threshold_sigma}σ`,trend:v.window?`窗口 ${v.window}`:'自动窗口',lag:`滞后 ${v.max_lag} / ${v.resample_interval_seconds||'自动'}秒`,change_point:`${v.window?'窗口 '+v.window:'自动窗口'} / ${v.threshold_sigma}σ`,pca:`${v.components}个主成分`,normality:`α=${v.alpha}`,acf_pacf:`滞后 ${v.max_lag}`,cross_correlation:`±${v.max_lag}步 / ${v.resample_interval_seconds||'自动'}秒`,spectrum:v.resample_interval_seconds?`${v.resample_interval_seconds}秒重采样`:'自动采样间隔',filtering:{moving_average:'滑动平均',median:'中值滤波',butterworth:'Butterworth'}[v.method]||v.method,time_drift:`前后${Math.round(v.window_fraction*100)}% / PSI ${v.psi_bins}箱`};return x[id]||'已配置'}
async function bootstrap(){const [a,d]=await Promise.all([get('/data-analysis/algorithms'),get('/datasets')]);algorithms.value=(a.items||[]).filter((item:any)=>item.id!=='anomaly_attribution');datasets.value=(d.items||d||[]).filter((item:any)=>item.has_file);await loadHistory()}
function parameterStorageKey(datasetId:number|string|null=form.value.dataset_id){return `${PARAMETER_STORAGE_PREFIX}${datasetId||'draft'}`}
function readLocalParameterSettings(datasetId:number){try{const raw=localStorage.getItem(parameterStorageKey(datasetId))||localStorage.getItem(parameterStorageKey('draft'));const saved=raw?JSON.parse(raw):{};return saved&&typeof saved==='object'&&!Array.isArray(saved)?saved:{}}catch{return {}}}
async function restoreParameterSettings(datasetId:number){const localSettings=readLocalParameterSettings(datasetId);try{const response:any=await get(`/data-analysis/parameter-settings/${datasetId}`);const saved=response?.settings;if(saved&&typeof saved==='object'&&!Array.isArray(saved)&&Object.keys(saved).length){form.value.algorithm_params=saved;localStorage.setItem(parameterStorageKey(datasetId),JSON.stringify(saved));return}}catch{/* 离线时仍使用本地草稿 */}form.value.algorithm_params=localSettings}
async function persistParameterSettings(){const settings=cloneParams(form.value.algorithm_params||{});try{localStorage.setItem(parameterStorageKey(),JSON.stringify(settings))}catch{/* 服务端保存仍是权威来源 */}if(form.value.dataset_id){await put(`/data-analysis/parameter-settings/${form.value.dataset_id}`,{settings})}}
async function loadColumns(id:number){columns.value={columns:[],numeric_columns:[],row_count:0};form.value.numeric_columns=[];form.value.time_column=null;form.value.target_column=null;form.value.time_range=[];if(!id)return;await restoreParameterSettings(id);try{columns.value=await get(`/data-analysis/datasets/${id}/columns`);form.value.time_column=columns.value.detected_time_column||null}catch(e:any){ElMessage.error(e?.message||'字段加载失败')}}
function startProgress(){progress.value=5;timer=window.setInterval(()=>{if(progress.value<92)progress.value+=Math.max(1,Math.round((94-progress.value)/10))},500)}
function stopProgress(){if(timer)clearInterval(timer);progress.value=100;setTimeout(()=>progress.value=0,500)}
function requiredAnalysisColumns(){const params=form.value.algorithm_params||{};return [...new Set([form.value.target_column,...(params.cca?.x_columns||[]),...(params.cca?.y_columns||[]),...(params.sensor_consistency?.sensor_columns||[]),params.operation_impact?.operation_column,...(params.operation_impact?.response_columns||[]),...(params.dynamic_regression?.driver_columns||[])].filter(Boolean))]}
async function runAnalysis(){if(!form.value.dataset_id)return ElMessage.warning('请选择数据集');if(!form.value.analyses.length)return ElMessage.warning('至少选择一种分析算法');running.value=true;startProgress();try{const [start_time,end_time]=form.value.time_range||[];const required=requiredAnalysisColumns();const selectedNumeric=form.value.numeric_columns.length?[...new Set([...form.value.numeric_columns,...required])]:null;const payload={...form.value,start_time:start_time||null,end_time:end_time||null,numeric_columns:selectedNumeric};delete payload.time_range;const response=await post('/data-analysis/runs',payload);current.value={...response,configuration:payload};operationImpactAi.value=null;const available=Object.keys(current.value.result.analyses);activeResult.value=current.value.result.analyses?.overview?'overview':(available[0]||'overview');distributionColumn.value=current.value.result.analyses.distribution?.items?.[0]?.column||'';normalityColumn.value=current.value.result.analyses.normality?.items?.[0]?.column||'';crossCorrelationColumn.value=current.value.result.analyses.cross_correlation?.items?.[0]?.column||'';await loadHistory();await nextTick();renderActiveChart();ElMessage.success('所选分析已完成并保存')}catch(e:any){ElMessage.error(e?.message||'分析失败')}finally{running.value=false;stopProgress()}}
function clearCharts(){charts.forEach(chart=>chart.dispose());charts=[]}
function chart(el:HTMLElement|undefined,option:any){if(!el)return;const instance=echarts.init(el);instance.setOption(option);charts.push(instance)}
async function renderBaseChart(){await nextTick();clearCharts();const a=analysis.value;const grid={left:70,right:30,bottom:80,top:45};if(activeResult.value==='distribution'&&selectedDistribution.value){const item=selectedDistribution.value;chart(mainChart.value,{tooltip:{trigger:'axis'},grid,xAxis:{type:'category',data:item.histogram.counts.map((_:any,i:number)=>`${item.histogram.bins[i]}~${item.histogram.bins[i+1]}`),axisLabel:{rotate:40}},yAxis:{type:'value'},series:[{type:'bar',data:item.histogram.counts}]})}else if(activeResult.value==='correlation'){const c=a.correlation?.[correlationMethod.value];if(!c)return;const values:any[]=[];c.matrix.forEach((row:any[],y:number)=>row.forEach((v:any,x:number)=>v!=null&&values.push([x,y,v])));chart(mainChart.value,{tooltip:{formatter:(p:any)=>`${c.columns[p.value[1]]} × ${c.columns[p.value[0]]}: ${p.value[2]}`},grid,xAxis:{type:'category',data:c.columns,axisLabel:{rotate:40}},yAxis:{type:'category',data:c.columns},visualMap:{min:-1,max:1,calculable:true,orient:'horizontal',bottom:0},series:[{type:'heatmap',data:values}]})}else if(activeResult.value==='dynamic_regression'&&a.dynamic_regression?.available){const series=a.dynamic_regression.series;chart(mainChart.value,{tooltip:{trigger:'axis'},legend:{top:0},grid:{...grid,top:55},xAxis:{type:'category',data:series.timestamps},yAxis:{type:'value',scale:true},dataZoom:[{type:'inside'},{type:'slider'}],series:[{name:'实际值',type:'line',showSymbol:false,data:series.actual},{name:'预测值',type:'line',showSymbol:false,data:series.predicted,lineStyle:{type:'dashed'}}]})}else if(activeResult.value==='operation_impact'&&a.operation_impact?.available){const responses=a.operation_impact.responses||[];const lags=[...new Set(responses.flatMap((item:any)=>item.timeline?.map((point:any)=>point.lag_seconds)||[]))].sort((x:any,y:any)=>x-y);chart(mainChart.value,{tooltip:{trigger:'axis'},legend:{top:0,type:'scroll'},grid:{...grid,top:62},xAxis:{type:'category',name:'操作后时间（秒）',data:lags},yAxis:{type:'value',name:'相对变更前的响应',scale:true},dataZoom:[{type:'inside'},{type:'slider'}],series:responses.map((item:any)=>({name:item.column,type:'line',showSymbol:false,data:lags.map((lag:any)=>item.timeline?.find((point:any)=>point.lag_seconds===lag)?.median_response??null)})).concat([{name:'零基线',type:'line',showSymbol:false,data:lags.map(()=>0),lineStyle:{type:'dashed',color:'#909399'},silent:true}])})}else if(activeResult.value==='cca'&&a.cca?.available){const items=a.cca.components||[];chart(mainChart.value,{tooltip:{trigger:'axis'},grid,xAxis:{type:'category',data:items.map((x:any)=>x.component)},yAxis:{type:'value',min:0,max:1,name:'典型相关系数'},series:[{type:'bar',name:'典型相关',data:items.map((x:any)=>x.correlation),itemStyle:{color:'#409eff'}}]})}else if(activeResult.value==='mutual_information'&&a.mutual_information?.available){const items=a.mutual_information.items.slice(0,25);chart(mainChart.value,{tooltip:{trigger:'axis'},grid,xAxis:{type:'category',data:items.map((x:any)=>x.column),axisLabel:{rotate:40}},yAxis:{type:'value',name:'互信息'},series:[{name:'互信息',type:'bar',data:items.map((x:any)=>x.mutual_information)}]})}else if(activeResult.value==='time_drift'&&a.time_drift?.available){const items=a.time_drift.items.slice(0,25);chart(mainChart.value,{tooltip:{trigger:'axis'},grid,xAxis:{type:'category',data:items.map((x:any)=>x.column),axisLabel:{rotate:40}},yAxis:{type:'value',name:'PSI'},series:[{name:'PSI',type:'bar',data:items.map((x:any)=>({value:x.psi,itemStyle:{color:x.level==='significant'?'#f56c6c':x.level==='warning'?'#e6a23c':'#67c23a'}})),markLine:{silent:true,symbol:'none',data:[{yAxis:.1,name:'关注'},{yAxis:.25,name:'显著'}]}}]})}else if(activeResult.value==='anomaly'){const items=a.anomaly.iqr.columns.slice(0,20);const sigma=new Map((a.anomaly.three_sigma?.columns||[]).map((x:any)=>[x.column,x.rate]));chart(mainChart.value,{tooltip:{trigger:'axis'},legend:{top:0},grid:{...grid,top:60},xAxis:{type:'category',data:items.map((x:any)=>x.column),axisLabel:{rotate:40}},yAxis:{type:'value',name:'异常率%'},series:[{name:'IQR',type:'bar',data:items.map((x:any)=>x.rate)},{name:a.anomaly.three_sigma?.algorithm||'3σ',type:'bar',data:items.map((x:any)=>sigma.get(x.column)||0)}]})}else if(activeResult.value==='trend'&&a.trend?.available){chart(mainChart.value,{tooltip:{trigger:'axis'},legend:{top:0},grid:{...grid,top:60},xAxis:{type:'category',data:a.trend.timestamps},yAxis:{type:'value',scale:true},dataZoom:[{type:'inside'},{type:'slider'}],series:a.trend.series.flatMap((s:any)=>[{name:s.column,type:'line',showSymbol:false,data:s.values},{name:`${s.column}移动平均`,type:'line',showSymbol:false,data:s.moving_average,lineStyle:{type:'dashed'}}])})}else if(activeResult.value==='lag'&&a.lag?.available){const items=a.lag.items.slice(0,20);chart(mainChart.value,{tooltip:{trigger:'axis'},grid,xAxis:{type:'category',data:items.map((x:any)=>x.column),axisLabel:{rotate:40}},yAxis:{type:'value',min:-1,max:1,name:'最佳相关'},series:[{type:'bar',data:items.map((x:any)=>x.best?.correlation||0)}]})}else if(activeResult.value==='pca'&&a.pca?.available){chart(mainChart.value,{tooltip:{trigger:'axis'},legend:{data:['单项解释方差','累计解释方差']},grid,xAxis:{type:'category',data:a.pca.explained_variance_ratio.map((_:any,i:number)=>`PC${i+1}`)},yAxis:{type:'value',name:'解释方差(%)',max:100},series:[{name:'单项解释方差',type:'bar',data:a.pca.explained_variance_ratio.map((value:number)=>value*100)},{name:'累计解释方差',type:'line',data:a.pca.cumulative_variance.map((value:number)=>value*100),markLine:{silent:true,symbol:'none',data:[{yAxis:80,name:'建议线 80%'}]}}]});chart(secondChart.value,{tooltip:{trigger:'item'},grid:{left:60,right:20,bottom:45,top:30},xAxis:{type:'value',name:'PC1'},yAxis:{type:'value',name:'PC2'},series:[{type:'scatter',symbolSize:5,data:a.pca.scatter}]})}}
async function renderActiveChart(){await nextTick();clearCharts();const a=analysis.value;const grid={left:70,right:30,bottom:80,top:45};if(activeResult.value==='normality'&&selectedNormality.value){const item=selectedNormality.value;const reference=item.qq_reference||[item.qq[0],item.qq[item.qq.length-1]];chart(mainChart.value,{tooltip:{trigger:'item'},grid,xAxis:{type:'value',name:'理论正态分位数',scale:true},yAxis:{type:'value',name:'样本分位数',scale:true},series:[{name:'QQ样本点',type:'scatter',symbolSize:5,data:item.qq},{name:'正态参考线',type:'line',showSymbol:false,data:reference,lineStyle:{type:'dashed'}}]})}else if(activeResult.value==='acf_pacf'&&a.acf_pacf?.available){const confidence=a.acf_pacf.confidence_95;chart(mainChart.value,{tooltip:{trigger:'axis'},legend:{top:0},grid:{...grid,top:60},xAxis:{type:'category',name:'滞后阶数',data:a.acf_pacf.lags},yAxis:{type:'value',min:-1,max:1,name:'相关系数'},series:[{name:'ACF',type:'bar',data:a.acf_pacf.acf,markLine:{silent:true,symbol:'none',lineStyle:{type:'dashed',color:'#e6a23c'},data:[{yAxis:confidence},{yAxis:-confidence}]}},{name:'PACF',type:'line',data:a.acf_pacf.pacf}]})}else if(activeResult.value==='cross_correlation'&&selectedCrossCorrelation.value){const item=selectedCrossCorrelation.value;chart(mainChart.value,{tooltip:{trigger:'axis'},grid,xAxis:{type:'category',name:'时间滞后（正值=字段早于目标）',data:item.correlations.map((x:any)=>x.lag_label)},yAxis:{type:'value',min:-1,max:1,name:'Pearson相关系数'},series:[{name:item.column,type:'line',data:item.correlations.map((x:any)=>x.correlation),markLine:{silent:true,symbol:'none',data:[{yAxis:0}]}}]})}else if(activeResult.value==='spectrum'&&a.spectrum?.available){chart(mainChart.value,{tooltip:{trigger:'axis'},grid,xAxis:{type:'value',name:'频率 (Hz)',scale:true},yAxis:{type:'value',name:'功率',scale:true},dataZoom:[{type:'inside'},{type:'slider'}],series:[{name:'FFT功率谱',type:'line',showSymbol:false,data:a.spectrum.frequencies_hz.map((frequency:number,index:number)=>[frequency,a.spectrum.power[index]])}]})}else if(activeResult.value==='filtering'&&a.filtering?.available){chart(mainChart.value,{tooltip:{trigger:'axis'},legend:{top:0},grid:{...grid,top:60},xAxis:{type:'category',data:a.filtering.timestamps},yAxis:{type:'value',scale:true},dataZoom:[{type:'inside'},{type:'slider'}],series:[{name:'原始信号',type:'line',showSymbol:false,data:a.filtering.original},{name:a.filtering.algorithm,type:'line',showSymbol:false,data:a.filtering.filtered,lineStyle:{width:2}}]})}else{await renderBaseChart()}}
async function explainOperationImpact(){if(!current.value?.id)return ElMessage.warning('请先运行或打开一条分析记录');if(!analysis.value.operation_impact?.available)return ElMessage.warning('当前记录没有可用的操作影响分析结果');operationImpactAiLoading.value=true;try{operationImpactAi.value=await post(`/data-analysis/runs/${current.value.id}/operation-impact-ai`,{});if(operationImpactAi.value?.available)ElMessage.success('AI 解读已生成');else ElMessage.warning(operationImpactAi.value?.warning||'AI 解读暂不可用')}catch(e:any){ElMessage.error(e?.message||'AI 解读请求失败')}finally{operationImpactAiLoading.value=false}}
async function loadHistory(){try{const r=await get('/data-analysis/runs');history.value=r.items||[]}catch(e:any){ElMessage.error(e?.message||'历史记录加载失败')}}
async function openRun(id:number){
  openingRunId.value=id
  try{
    const r=await get(`/data-analysis/runs/${id}`)
    current.value=r
    operationImpactAi.value=null
    const available=Object.keys(r.result?.analyses||{})
    // 历史报告优先展示轻量概览，图表页在用户点击时才创建。
    activeResult.value=r.result?.analyses?.overview?'overview':(available[0]||'overview')
    distributionColumn.value=r.result?.analyses?.distribution?.items?.[0]?.column||''
    normalityColumn.value=r.result?.analyses?.normality?.items?.[0]?.column||''
    crossCorrelationColumn.value=r.result?.analyses?.cross_correlation?.items?.[0]?.column||''
    await nextTick()
    renderActiveChart()
    window.scrollTo({top:400,behavior:'smooth'})
  }catch(e:any){ElMessage.error(e?.message||'记录加载失败')}
  finally{openingRunId.value=null}
}
async function removeRun(row:any){try{await ElMessageBox.confirm(`确定删除分析记录 #${row.id} 吗？`,'删除记录',{type:'warning'});await del(`/data-analysis/runs/${row.id}`);await loadHistory();ElMessage.success('已删除')}catch(e:any){if(e!=='cancel')ElMessage.error(e?.message||'删除失败')}}
async function saveSegmentAsDataset(segment:any){if(!current.value)return;try{const suggested=`${result.value.source_name}运行段${segment.segment_id}`;const {value}=await ElMessageBox.prompt('可修改生成后的数据集名称。','保存运行段为数据集',{inputValue:suggested,inputPlaceholder:'数据集名称',inputValidator:(v:string)=>v?.trim()?true:'请输入数据集名称'});const response=await post(`/data-analysis/runs/${current.value.id}/segments/${segment.segment_id}/dataset`,{name:value.trim()});ElMessage.success(`已生成数据集 #${response.dataset.id} ${response.dataset.name}`);await bootstrap()}catch(e:any){if(e!=='cancel')ElMessage.error(e?.message||'保存运行段失败')}}
function downloadReport(){if(!current.value)return;const blob=new Blob([JSON.stringify(current.value,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`data_analysis_${current.value.id}.json`;a.click();URL.revokeObjectURL(url)}
function downloadTimeGaps(){const items=analysis.value.time_quality?.gap_examples||[];if(!items.length)return;const headers=['缺口前时间','缺口后时间','缺口时长(秒)','缺口时长','估计缺失点数','类型'];const rows=items.map((item:any)=>[item.before_time,item.after_time,item.gap_seconds,item.gap_label,item.estimated_missing_points,item.kind]);const csv=[headers,...rows].map(row=>row.map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(',')).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`data_analysis_${current.value?.id||'run'}_time_gaps.csv`;a.click();URL.revokeObjectURL(url)}
function algorithmNames(ids:string[]=[]){return ids.map(id=>algorithms.value.find(a=>a.id===id)?.name||id).join('、')}
function statLabel(key:any){return({count:'数量',mean:'均值',std:'标准差',min:'最小值',q1:'下四分位',median:'中位数',q3:'上四分位',max:'最大值',skew:'偏度'} as any)[key]||key}
function sigmaSuitability(column:string){const item=analysis.value.normality?.items?.find((entry:any)=>entry.column===column);if(!item)return{type:'info',text:'未运行正态性检验'};return item.is_normal?{type:'success',text:'近似正态，可重点参考3σ'}:{type:'warning',text:'非正态，建议参考IQR'}}
function driftTagType(level:string){return level==='significant'?'danger':level==='warning'?'warning':'success'}
function driftLevelLabel(level:string){return level==='significant'?'显著漂移':level==='warning'?'需要关注':'稳定'}
function topLoadings(values:Record<string,number>){return Object.entries(values).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).slice(0,5).map(([k,v])=>`${k}(${Number(v).toFixed(3)})`).join('、')}
function formatDate(value:string){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'-'}
function resize(){charts.forEach(c=>c.resize())}
onMounted(()=>{bootstrap();window.addEventListener('resize',resize)});onBeforeUnmount(()=>{if(timer)clearInterval(timer);clearCharts();window.removeEventListener('resize',resize)})
</script>

